function generateCIConfig(provider, config) {
  if (provider === 'github') {
    return `name: ${config.name || 'CI'}

on:
  push:
    branches: [${(config.branches || ['main']).join(', ')}]
  pull_request:
    branches: [${(config.branches || ['main']).join(', ')}]

jobs:
  lint:
    runs-on: ${config.runsOn || 'ubuntu-latest'}
    steps:
      - uses: actions/checkout@v4
      - name: Install dependencies
        run: ${config.installCmd || 'npm ci'}
      - name: Lint
        run: ${config.lintCmd || 'npm run lint'}

  test:
    runs-on: ${config.runsOn || 'ubuntu-latest'}
    needs: lint
    steps:
      - uses: actions/checkout@v4
      - name: Install dependencies
        run: ${config.installCmd || 'npm ci'}
      - name: Run tests
        run: ${config.testCmd || 'npm test'}

  build:
    runs-on: ${config.runsOn || 'ubuntu-latest'}
    needs: test
    steps:
      - uses: actions/checkout@v4
      - name: Install dependencies
        run: ${config.installCmd || 'npm ci'}
      - name: Build
        run: ${config.buildCmd || 'npm run build'}

  deploy:
    runs-on: ${config.runsOn || 'ubuntu-latest'}
    needs: build
    if: github.ref == 'refs/heads/${(config.branches || ['main'])[0]}'
    steps:
      - uses: actions/checkout@v4
      - name: Deploy
        run: ${config.deployCmd || 'echo "Deploying..."'}`;
  }
  return 'Unsupported provider: ' + provider;
}

const config = {
  name: 'Node CI',
  branches: ['main', 'develop'],
  installCmd: 'npm ci',
  lintCmd: 'npm run lint',
  testCmd: 'npm test',
  buildCmd: 'npm run build'
};

console.log(generateCIConfig('github', config));

