class HealthCheckRunner {
  constructor(checks) {
    this.checks = checks;
  }

  async runCheck(check) {
    // Simulate health check with delay
    return new Promise((resolve) => {
      const timeout = setTimeout(() => {
        resolve({ name: check.name, status: 'timeout', passed: false, latency: check.timeout + 'ms' });
      }, check.timeout || 5000);

      // Simulate success/failure based on expectedStatus
      setTimeout(() => {
        clearTimeout(timeout);
        const simulatedStatus = Math.random() > 0.2 ? check.expectedStatus || 200 : 500;
        const passed = simulatedStatus === (check.expectedStatus || 200);
        resolve({
          name: check.name,
          url: check.url,
          status: passed ? 'ok' : 'fail',
          httpStatus: simulatedStatus,
          passed,
          latency: Math.floor(Math.random() * 200) + 50 + 'ms'
        });
      }, Math.floor(Math.random() * 200) + 100);
    });
  }

  async runAll() {
    const results = await Promise.all(this.checks.map(c => this.runCheck(c)));
    const passed = results.filter(r => r.passed).length;
    console.log(`Health check results: ${passed}/${results.length} passed`);
    return { passed, total: results.length, results };
  }
}

const checks = [
  { name: 'API Health', url: '/health', expectedStatus: 200, timeout: 3000 },
  { name: 'Database', url: '/db/status', expectedStatus: 200, timeout: 3000 },
  { name: 'Cache', url: '/cache/ping', expectedStatus: 200, timeout: 2000 }
];

const runner = new HealthCheckRunner(checks);
runner.runAll().then(summary => {
  for (const r of summary.results) {
    console.log(`${r.passed ? '✓' : '✗'} ${r.name}: ${r.status} (${r.latency})`);
  }
});

