interface StageResult {
  stage: string;
  status: 'passed' | 'failed';
  duration: string;
  error?: string;
}

class DeploymentOrchestrator {
  name: string;
  results: StageResult[] = [];

  constructor(name: string) {
    this.name = name;
  }

  async stage(name: string, action: () => Promise<boolean>): Promise<boolean> {
    const start = Date.now();
    try {
      const result = await action();
      const duration = Date.now() - start;
      const entry: StageResult = { stage: name, status: result ? 'passed' : 'failed', duration: duration + 'ms' };
      this.results.push(entry);
      console.log(`${entry.status === 'passed' ? '✓' : '✗'} ${name}: ${entry.duration}`);
      return entry.status === 'passed';
    } catch (err) {
      const duration = Date.now() - start;
      this.results.push({ stage: name, status: 'failed', duration: duration + 'ms', error: (err as Error).message });
      console.log(`✗ ${name}: FAILED - ${(err as Error).message}`);
      return false;
    }
  }

  async run(): Promise<void> {
    console.log(`=== Deploying: ${this.name} ===`);

    if (!await this.stage('Build', () => new Promise(r => setTimeout(() => r(true), 200)))) return this.report();
    if (!await this.stage('Test', () => new Promise(r => setTimeout(() => r(true), 300)))) return this.report();
    if (!await this.stage('Health Check', () => new Promise(r => setTimeout(() => r(true), 200)))) return this.report();
    await this.stage('Deploy', () => new Promise(r => setTimeout(() => r(true), 400)));
    await this.stage('Post-Deploy Check', () => new Promise(r => setTimeout(() => r(true), 200)));

    this.report();
  }

  report(): void {
    console.log('\n=== Deployment Report ===');
    for (const r of this.results) {
      const icon = r.status === 'passed' ? '✓' : '✗';
      console.log(`${icon} ${r.stage}: ${r.status} (${r.duration})${r.error ? ' - ' + r.error : ''}`);
    }
    const passed = this.results.filter(r => r.status === 'passed').length;
    const failed = this.results.filter(r => r.status === 'failed').length;
    console.log(`\nResult: ${passed} passed, ${failed} failed`);
  }
}

const deploy = new DeploymentOrchestrator('my-app');
deploy.run();
